import { BinaryTaskType, } from "../Thread.types.js";
import { Threads } from "../Threads.js";
import { ThreadsInternalMessageIds, } from "../Internal/Messages.js";
import { InternalTasks, MessageCursors } from "../Internal/InternalTasks.js";
const binaryTaskType = new BinaryTaskType();
const tempTransfers = [];
export class Thread {
    name;
    index;
    threadPoolName;
    static readySet = new Set();
    get isRemoteReady() {
        return Thread.readySet.has(this);
    }
    get isPortSet() {
        return Boolean(this.port);
    }
    port = null;
    _pool = null;
    constructor(name, index, threadPoolName = "worker", threadPool = null) {
        this.name = name;
        this.index = index;
        this.threadPoolName = threadPoolName;
        this._pool = threadPool;
    }
    setPort(port) {
        this.port = port;
        if (Threads.environment == "browser") {
            const p = port;
            p.onmessage = (event) => {
                InternalTasks.runInternal(event.data, this, event);
            };
            p.onmessageerror = (event) => {
                console.error(`Error occured in from thread ${this.name}`);
                console.log(event.data);
                console.log(event);
            };
        }
        if (Threads.environment == "node") {
            const p = port;
            p.on("message", (data) => {
                InternalTasks.runInternal(data, this, data);
            });
            p.on("error", (data) => {
                console.error(`Error occured in from thread ${this.name}`);
                console.log(data);
            });
        }
        this.sendMessage([
            ThreadsInternalMessageIds.setReady,
            this.name,
            this.index,
        ]);
    }
    sendMessage(data, transfers) {
        if (!this.port) {
            throw new Error(`Cannot send message to thread [${this.name}] port is not set`);
        }
        this.port.postMessage(data, Threads.environment == "browser" && transfers ? transfers : undefined);
    }
    connectToThread(otherThread) {
        const channel = new MessageChannel();
        otherThread.sendMessage([
            ThreadsInternalMessageIds.connectPort,
            this.name,
            this.threadPoolName,
            channel.port1,
        ], [channel.port1]);
        this.sendMessage([
            ThreadsInternalMessageIds.connectPort,
            otherThread.name,
            otherThread.threadPoolName,
            channel.port2,
        ], [channel.port2]);
    }
    waitTillTaskExist(id, checkInterval = 50) {
        let readyToGo = false;
        return new Promise((resolve) => {
            const onExist = (exists) => {
                if (readyToGo) {
                    return clearTimeout(t);
                }
                if (exists) {
                    readyToGo = true;
                    resolve(true);
                    clearTimeout(t);
                }
                else {
                    setTimeout(checkIfExists, checkInterval);
                }
            };
            const checkIfExists = () => {
                this.taskExist(id, onExist);
            };
            let t = setTimeout(checkIfExists, checkInterval);
        });
    }
    taskExist(id, onDone) {
        const promiseId = InternalTasks.getPromiseId();
        MessageCursors.checkTasks[1] = id;
        MessageCursors.checkTasks[2] = promiseId;
        InternalTasks.addPromiseTakss("tasks-check", promiseId, (data) => {
            onDone(data);
        });
        this.sendMessage(MessageCursors.checkTasks);
    }
    runTask(id, data, transfers, onDone) {
        const promiseId = onDone ? InternalTasks.getPromiseId() : -1;
        if (onDone)
            InternalTasks.addPromiseTakss(id, promiseId, onDone);
        MessageCursors.runTask[1] = id;
        MessageCursors.runTask[2] = promiseId;
        MessageCursors.runTask[3] = data;
        this.sendMessage(MessageCursors.runTask, transfers);
        MessageCursors.runTask[3] = null;
    }
    runTaskAsync(id, data, transfers) {
        return new Promise((resolve) => {
            this.runTask(id, data, transfers, (data) => {
                resolve(data);
            });
        });
    }
    runBinaryTask(id, data, onDone) {
        const promiseId = onDone ? InternalTasks.getPromiseId() : -1;
        if (onDone)
            InternalTasks.addPromiseTakss(id, promiseId, onDone);
        const hashed = InternalTasks.getHashedTaskId(id);
        binaryTaskType.view = data;
        binaryTaskType.taskId = hashed;
        binaryTaskType.promiseId = promiseId;
        tempTransfers[0] = data.buffer;
        this.sendMessage(data.buffer, tempTransfers);
        tempTransfers[0] = null;
    }
    runBinaryTaskAsync(id, data) {
        return new Promise((resolve) => {
            this.runBinaryTask(id, data, (data) => {
                resolve(data);
            });
        });
    }
    waitTillReady() {
        return new Promise((resolve, reject) => {
            const inte = setInterval(() => {
                if (this.isPortSet) {
                    clearInterval(inte);
                    resolve(true);
                }
            }, 1);
        });
    }
    destroy() {
        Thread.readySet.delete(this);
        if (!this.port)
            return;
        if ("terminate" in this.port) {
            this.port.terminate();
        }
    }
}
